def drive(me, enemy, arena):
    try:
        b = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        t = b / 90.0
        if t > 1.0:
            t = 1.0
        if t < -1.0:
            t = -1.0
        if me.on_side or me.righting:
            return (0.0, 0.0)
        if d > 1.2:
            l = 1.0 - t
            r = 1.0 + t
        else:
            l = 0.3 - 0.9 * t
            r = 0.3 + 0.9 * t
        if l > 1.0:
            l = 1.0
        if l < -1.0:
            l = -1.0
        if r > 1.0:
            r = 1.0
        if r < -1.0:
            r = -1.0
        return (l, r)
    except Exception:
        return (0.0, 0.0)

